(function(window){
  'use strict';
  const FIVE_S=[
    ['workstationClean','Workstation Clean',true,'sparkle','green','Confirm the workstation and surrounding work surface are clean.'],
    ['toolsOrganized','Tools Organized',true,'wrench','blue','Confirm tools are organized, accounted for and ready for safe use.'],
    ['materialsStored','Materials / Parts Properly Stored',true,'gear','amber','Confirm materials and parts are identified and stored correctly.'],
    ['wasteRemoved','Waste Removed',true,'trash','orange','Confirm production waste and discarded packaging have been removed.'],
    ['areaClear','Walking / Working Area Clear',false,'walkway','teal','Confirm walking and working routes are clear of obstruction.'],
    ['safetyHazard','No Obvious Safety Hazard',false,'shield','purple','Confirm no obvious safety hazard is present in the work area.']
  ];
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const uid=prefix=>`${prefix}-${window.crypto.randomUUID()}`,today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto'}).format(new Date());
  const emptyReport=project=>({requestId:uid('daily'),reportId:'',reportDate:today(),shift:'Day',customShift:'',completedQty:0,reworkQty:0,defectiveQty:0,holdQty:0,workPerformed:'',issueStatus:'No',issueDescription:'',actionTaken:'',submittedBy:project.updatedBy||project.activatedBy||'',productionEvidence:[],fiveS:Object.fromEntries(FIVE_S.map(([key,,required])=>[key,{required,status:null,note:'',evidence:[]}]))});
  const source=ref=>ref.pendingImage?`data:${ref.pendingImage.type};base64,${ref.pendingImage.base64}`:ref.url?window.MkiteApiConfig.baseUrl.replace(/\/$/,'')+ref.url:'';
  const ICONS={sparkle:'<path d="M5 18h8M7 18v2h4v-2M9 3a5 5 0 0 0-3 9c.7.5 1 1.2 1 2h4c0-.8.3-1.5 1-2a5 5 0 0 0-3-9Zm7 1v3m-1.5-1.5h3M16 11v2m-1-1h2"/>',wrench:'<path d="M14 6a4 4 0 0 0-5 5L3 17l3 3 6-6a4 4 0 0 0 5-5l-2 2-2-2 1-3Z"/>',gear:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-5 1 2.2 2.3.7 2-1 1.8 1.8-1 2 .7 2.3L21 12l-2.2 1-.7 2.3 1 2-1.8 1.8-2-1-2.3.7L12 21l-1-2.2-2.3-.7-2 1-1.8-1.8 1-2L5.2 13 3 12l2.2-1 .7-2.3-1-2 1.8-1.8 2 1 2.3-.7L12 3Z"/>',trash:'<path d="M4 7h16M9 3h6l1 4H8l1-4Zm-2 4 1 14h8l1-14M10 11v6m4-6v6"/>',walkway:'<path d="M12 4a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm-2 3 2-2 2 2 1 4-3 2-2 8M8 10l-3 4m9-1 4 3M4 22h16"/>',shield:'<path d="M12 2 4 5v6c0 5 3.4 9 8 11 4.6-2 8-6 8-11V5l-8-3Zm-3 10 2 2 4-5"/>',document:'<path d="M6 2h8l4 4v16H6V2Zm8 0v5h5M9 11h6M9 15h6M9 19h4"/>',camera:'<path d="M4 7h4l1.5-2h5L16 7h4v12H4V7Zm8 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z"/>',checklist:'<path d="M9 6h11M9 12h11M9 18h11M3 6l1.5 1.5L7 4M3 12l1.5 1.5L7 10M3 18l1.5 1.5L7 16"/>'};
  const icon=(name,label='')=>`<svg class="five-s-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" ${label?`role="img" aria-label="${esc(label)}"`:'aria-hidden="true"'}>${ICONS[name]}</svg>`;
  const cameraIcon=()=>'<svg class="five-s-camera" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h4l1.5-2h5L16 7h4v12H4V7Zm8 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z"/></svg>';
  const chevronIcon=()=>'<svg class="five-s-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';
  function fiveSScore(report){const evaluated=FIVE_S.filter(([key])=>Boolean(report.fiveS?.[key]?.status)).length,percent=Math.round(evaluated/FIVE_S.length*1000)/10;return {evaluated,total:FIVE_S.length,percent,display:Math.round(percent)};}
  function quantityContext(project,report){const projectQuantity=Number(project?.totalProjectQuantity)||0,previouslyCompleted=(project?.dailyReportData?.reports||[]).filter(item=>item.status==='Submitted'&&item.reportId!==report.reportId).reduce((sum,item)=>sum+(Number(item.completedQty)||0),0),availableQuantity=Math.max(projectQuantity-previouslyCompleted,0),attemptedCompleted=Number(report.completedQty);return {projectQuantity,previouslyCompleted,availableQuantity,attemptedCompleted,valid:Number.isSafeInteger(attemptedCompleted)&&attemptedCompleted>=0&&attemptedCompleted<=availableQuantity};}
  const quantityValidationError=context=>({path:'completedQty',code:'COMPLETED_QUANTITY_EXCEEDS_PROJECT_TOTAL',message:`Completed quantity ${context.attemptedCompleted} exceeds available quantity ${context.availableQuantity}.`});
  function moduleState(report,errors=[],project){const quantity=quantityContext(project||{totalProjectQuantity:Number.MAX_SAFE_INTEGER,dailyReportData:{reports:[]}},report),productionComplete=Boolean(report.reportDate&&report.shift&&String(report.submittedBy||'').trim()&&quantity.valid&&String(report.workPerformed||'').trim()&&['No','Yes'].includes(report.issueStatus)&&(report.issueStatus!=='Yes'||String(report.issueDescription||'').trim()&&String(report.actionTaken||'').trim())),productionStarted=Boolean(String(report.workPerformed||'').trim()||Number(report.completedQty)||Number(report.reworkQty)||Number(report.defectiveQty)||Number(report.holdQty)||report.issueStatus==='Yes'),evidenceComplete=Boolean(report.productionEvidence?.length),score=fiveSScore(report),requiredComplete=FIVE_S.filter(([, ,required])=>required).every(([key])=>{const item=report.fiveS?.[key];return Boolean(item?.status&&item.evidence?.length&&(item.status!=='Fail'||String(item.note||'').trim()));}),hasError=prefix=>errors.some(error=>error.path===prefix||error.path.startsWith(`${prefix}.`)),productionAttention=!quantity.valid||errors.some(error=>!error.path.startsWith('fiveS.')&&error.path!=='productionEvidence');return {production:{complete:productionComplete,started:productionStarted,attention:productionAttention},evidence:{complete:evidenceComplete,started:evidenceComplete,attention:hasError('productionEvidence')},fiveS:{complete:requiredComplete,started:score.evaluated>0,attention:hasError('fiveS'),score},ready:productionComplete&&evidenceComplete&&requiredComplete};}
  const normalizedReport=raw=>{const report=structuredClone(raw);report.productionEvidence||=[];report.fiveS||={};for(const [key,,required] of FIVE_S)report.fiveS[key]={required,status:null,note:'',evidence:[],...report.fiveS[key]};return report;};
  function compactEvidence(list,scope,label='+ ADD PHOTO'){return `<div class="daily-evidence-compact" data-daily-path="${scope}"><label class="evidence-upload">${label}<input type="file" accept="image/*" capture="environment" data-daily-upload="${scope}"></label><div class="daily-thumbnails">${list.map(ref=>`<span><img src="${esc(source(ref))}" alt="Daily report evidence"><button type="button" data-daily-action="remove-photo" data-ref="${esc(ref.assetId||ref.localId)}" aria-label="Remove picture">×</button></span>`).join('')}</div><small class="field-error" role="alert"></small></div>`;}
  function fiveSChecklist(report){const score=fiveSScore(report),requiredDone=FIVE_S.filter(([key,,required])=>required&&report.fiveS[key].status&&report.fiveS[key].evidence.length).length;return `<section class="daily-five-s-compact"><div class="daily-section-title"><div><span class="project-eyebrow">DAILY 5S / WORK AREA CHECK</span><small>${score.evaluated} of 6 checks evaluated · Required ${requiredDone}/4 complete</small></div><div class="five-s-score"><span>5S SCORE</span><strong>${score.display}%</strong></div></div><div class="five-s-segments" role="progressbar" aria-label="5S evaluation completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${score.display}" aria-valuetext="${score.evaluated} of 6 checks evaluated">${FIVE_S.map(([key,,,iconName,color])=>`<span class="five-s-${color}${report.fiveS[key].status?' is-evaluated':''}" title="${esc(key)}">${icon(iconName)}</span>`).join('')}</div><div class="daily-five-s-list">${FIVE_S.map(([key,label,required,iconName,color],index)=>{const item=report.fiveS[key],done=Boolean(item.status&&item.evidence.length),status=item.status||'Pending';return `${index===4?'<div class="daily-five-s-optional">OPTIONAL</div>':''}<button type="button" class="daily-five-s-row five-s-${color}${done?' is-complete':''}${item.status==='Fail'?' is-fail':''}" data-daily-action="open-five-s" data-ref="${key}" data-daily-path="fiveS.${key}.status" style="--five-s-color:var(--five-s-${color})"><span class="daily-check">${done?'✓':'○'}</span><span class="five-s-row-icon">${icon(iconName,`${label} icon`)}</span><span class="five-s-row-copy"><strong>${esc(label)}</strong><small class="five-s-status ${item.status==='Pass'?'is-pass':item.status==='Fail'?'is-fail':''}">${esc(status)}${!item.status&&required?' · Photo required':!item.status?' · Optional':''}</small><small class="field-error" role="alert"></small></span><span class="daily-photo-count">${item.evidence.length?`${cameraIcon()}<b>${item.evidence.length}</b>`:'ADD'}</span>${chevronIcon()}</button>`;}).join('')}</div></section>`;}
  function stateLabel(item,empty='NOT STARTED'){return item.attention?'<span class="daily-module-status is-attention">NEEDS CORRECTION</span>':item.complete?'<span class="daily-module-status is-complete">✓ COMPLETED</span>':item.started?'<span class="daily-module-status is-progress">IN PROGRESS</span>':`<span class="daily-module-status">${empty}</span>`;}
  function moduleCard(number,type,title,description,iconName,accent,status,summary,action){return `<button type="button" class="daily-module-card daily-module-${accent}${status.complete?' is-complete':''}${status.attention?' is-attention':''}" data-daily-action="open-module" data-ref="${type}" aria-label="${action}: ${title}"><span class="daily-module-top"><b>${number}</b><span class="daily-module-icon">${icon(iconName)}</span></span><span class="daily-module-title">${title}</span><span class="daily-module-description">${description}</span>${stateLabel(status,type==='evidence'?'PHOTOS REQUIRED':'NOT STARTED')}<span class="daily-module-summary">${summary}</span><span class="daily-module-action">${action}${chevronIcon()}</span></button>`;}
  function reportForm(project,state){const report=state.report,quantityReady=Number(project.totalProjectQuantity)>0,modules=moduleState(report,state.errors,project),score=modules.fiveS.score,validCount=[modules.production,modules.evidence,modules.fiveS].filter(item=>item.complete&&!item.attention).length,failure=state.failure,progress=state.progress||{percent:0,label:'Ready'};return `<form class="projects-panel daily-report-form daily-module-home" id="daily-report-form" novalidate><div class="daily-title-row"><div><span class="project-eyebrow">TODAY'S DAILY REPORT</span><h3>${report.reportId?'Continue daily report':'Daily report workspace'}</h3></div>${report.reportId?`<small>${esc(report.reportId)}</small>`:''}</div>${quantityReady?'':'<div class="daily-quantity-required"><strong>PROJECT QUANTITY REQUIRED</strong><span>Set the total quantity before submitting. Draft saving remains available.</span></div>'}<div class="daily-module-grid">${moduleCard('01','production','PRODUCTION REPORT',"Record today's production data, work performed and any issues.",'document','green',modules.production,modules.production.started?`Completed ${Number(report.completedQty)||0} · Re-work ${Number(report.reworkQty)||0}<br>${esc(report.shift)} shift · ${esc(report.submittedBy||'Not assigned')}`:'Date, shift, quantities, work and issues','OPEN PRODUCTION REPORT')}${moduleCard('02','evidence','PRODUCTION EVIDENCE',"Upload photos or take pictures of today's production evidence.",'camera','blue',modules.evidence,`${report.productionEvidence.length} PHOTO${report.productionEvidence.length===1?'':'S'}`,'OPEN PRODUCTION EVIDENCE')}${moduleCard('03','fiveS','DAILY 5S / WORK AREA CHECK',"Complete today's workplace safety and organization check.",'checklist','amber',modules.fiveS,`5S SCORE ${score.display}%<br>${score.evaluated} / 6 CHECKS`,'OPEN 5S CHECK')}</div><div class="daily-readiness-strip ${modules.ready?'is-ready':''}"><div><span class="project-eyebrow">DAILY REPORT STATUS</span><strong>${modules.ready?'✓ READY TO SUBMIT':'COMPLETE ALL REQUIRED MODULES'}</strong></div><small>${validCount} / 3 modules valid</small></div><div class="daily-action-bar"><div class="daily-action-progress${failure?' is-failed':''}" aria-live="polite"><div><strong>${esc(failure?.title||progress.label)}</strong><b>${progress.percent}%</b></div><div class="save-progress-track" role="progressbar" aria-label="Daily report save workflow" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.percent}"><span style="width:${progress.percent}%"></span></div>${failure?`<p>${esc(failure.message)}</p>${failure.details?`<small>Project Total: ${failure.details.projectQuantity} · Previously Completed: ${failure.details.previouslyCompleted} · Available: ${failure.details.availableQuantity} · Entered: ${failure.details.attemptedCompleted}</small>`:''}`:''}</div>${failure?.retryable?'<button class="button" type="button" data-daily-action="retry">RETRY</button>':''}${failure?.kind==='validation'?'<button class="button" type="button" data-daily-action="open-module" data-ref="production">OPEN PRODUCTION REPORT</button><button class="button" type="button" data-daily-action="open-quantity">UPDATE TOTAL QUANTITY</button>':''}<button class="button" type="button" data-daily-action="save-draft">SAVE DRAFT</button><button class="button button-primary" type="button" data-daily-action="submit-report"${quantityReady&&modules.ready?'':' disabled'}>SUBMIT DAILY REPORT</button></div></form>`;}
  function projectProgress(project){const progress=project.projectProgress||{percent:0,completed:0,total:0,remaining:0},difference=(project.totalProjectQuantity||0)-(project.originalProjectQuantity||0),complete=progress.total>0&&progress.completed>=progress.total;return `<section class="daily-side-card project-progress-card"><div><span class="project-eyebrow">PROJECT PROGRESS</span><strong class="daily-progress-score">${progress.percent.toFixed(1)}%</strong></div><div class="save-progress-track"><span style="width:${Math.min(progress.percent,100)}%"></span></div><p><b>${progress.completed.toLocaleString()}</b> / ${progress.total.toLocaleString()} completed · ${progress.remaining.toLocaleString()} remaining</p><dl><div><dt>Original</dt><dd>${project.originalProjectQuantity?.toLocaleString()||'Not set'}</dd></div><div><dt>Current</dt><dd>${project.totalProjectQuantity?.toLocaleString()||'Not set'}${difference?` <small>${difference>0?'+':''}${difference.toLocaleString()}</small>`:''}</dd></div></dl>${complete?'<small class="project-quantity-complete">✓ PROJECT QUANTITY COMPLETED</small>':''}<button class="button" data-daily-action="open-quantity">${project.totalProjectQuantity?'UPDATE TOTAL QUANTITY':'SET PROJECT QUANTITY'}</button></section>`;}
  function activeStaff(project){const active=project.staffingData.members.filter(member=>member.status==='Active');return `<section class="daily-side-card"><div class="daily-side-heading"><span class="project-eyebrow">ACTIVE STAFF</span><strong>${active.length}</strong></div><div class="daily-staff-compact">${active.map(member=>`<div><span>${esc(member.name)}</span><b>Active</b></div>`).join('')||'<small>No active staff.</small>'}</div><button class="button" data-daily-action="open-staff">MANAGE STAFF</button></section>`;}
  function readiness(project){const count=project.preparationReadiness?.count??6;return `<section class="daily-side-card daily-readiness"><span class="project-eyebrow">PREPARATION</span><strong>✓ ${count} / 6 Ready</strong><button class="button" data-daily-action="open-readiness">VIEW DETAILS</button></section>`;}
  function history(project){const reports=[...(project.dailyReportData?.reports||[])].sort((a,b)=>String(b.submittedAt||b.updatedAt||'').localeCompare(String(a.submittedAt||a.updatedAt||'')));return `<section class="projects-panel daily-history"><div class="daily-history-heading"><span class="project-eyebrow">PAST DAILY REPORTS</span><p>Submitted reports are read-only. Drafts can be reopened.</p></div><div class="activation-table"><table><thead><tr><th>Date</th><th>Shift</th><th>Completed</th><th>Re-work</th><th>Defective</th><th>Hold</th><th>Issues</th><th>By</th><th>Saved</th><th>Photos</th><th>Status</th><th>Action</th></tr></thead><tbody>${reports.map(report=>{const photos=(report.productionEvidence?.length||0)+FIVE_S.reduce((sum,[key])=>sum+(report.fiveS?.[key]?.evidence?.length||0),0);return `<tr><td>${esc(report.reportDate)}</td><td>${esc(report.shift==='Other'&&report.customShift?report.customShift:report.shift)}</td><td>${report.completedQty}</td><td>${report.reworkQty}</td><td>${report.defectiveQty}</td><td>${report.holdQty}</td><td>${esc(report.issueStatus)}</td><td>${esc(report.submittedBy)}</td><td>${esc(report.submittedAt||report.updatedAt||'—')}</td><td>${photos}</td><td>${esc(report.status)}</td><td><button class="button" data-daily-action="${report.status==='Draft'?'open-report':'view-report'}" data-ref="${esc(report.reportId)}">${report.status==='Draft'?'OPEN / EDIT':'VIEW'}</button></td></tr>`;}).join('')||'<tr><td colspan="12">No daily reports saved yet.</td></tr>'}</tbody></table></div></section>`;}
  const reportSnapshot=report=>JSON.stringify(report);
  const reportCounts=project=>{const reports=project.dailyReportData?.reports||[];return {submitted:reports.filter(report=>report.status==='Submitted').length,drafts:reports.filter(report=>report.status==='Draft').length};};
  const hasUnsavedReport=state=>Boolean(state.baseline&&reportSnapshot(state.report)!==state.baseline);
  function finalizingPanel(project){if(project.projectStatus!=='In-Progress')return '';return `<section class="projects-panel project-finalizing-entry"><span class="finalizing-entry-icon" aria-hidden="true">!</span><div><span class="project-eyebrow">PROJECT FINALIZING</span><h3>Ready to move this project forward?</h3><p>Enter Finalizing when production work is complete enough for final review. Ensure daily reports, evidence and 5S checks are saved before proceeding.</p></div><button class="button finalizing-entry-button" type="button" aria-label="Go to Project Finalizing" data-daily-action="open-finalizing">GO TO FINALIZING</button></section>`;}
  function finalizingModal(project,state){const counts=reportCounts(project),dirty=hasUnsavedReport(state),modules=moduleState(state.report,state.errors),progress=project.projectProgress||{percent:0,completed:0,total:0};return `<div class="daily-sheet-backdrop"><section class="daily-sheet project-finalizing-modal" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div><span class="project-eyebrow">CONFIRM LIFECYCLE CHANGE</span><h3 id="daily-sheet-title">Move project to Finalizing?</h3><p>This ends daily In-Progress reporting and opens the Finalizing workspace.</p></div><button class="button" type="button" data-daily-action="close-modal">CLOSE</button></div><dl class="activation-facts"><div><dt>PROJECT PROGRESS</dt><dd>${Number(progress.percent||0).toFixed(1)}%</dd></div><div><dt>COMPLETED</dt><dd>${Number(progress.completed||0).toLocaleString()} / ${Number(progress.total||0).toLocaleString()}</dd></div><div><dt>SUBMITTED REPORTS</dt><dd>${counts.submitted}</dd></div><div><dt>SAVED DRAFTS</dt><dd>${counts.drafts}</dd></div><div><dt>CURRENT LOCAL REPORT</dt><dd>${dirty?'Unsaved changes':modules.ready?'Complete':'Incomplete'}</dd></div></dl>${counts.drafts?`<div class="finalizing-warning"><strong>${counts.drafts} saved draft${counts.drafts===1?' remains':'s remain'}.</strong> Saved drafts will be preserved for project records.</div>`:''}${dirty?'<div class="finalizing-warning is-blocking"><strong>Save your current daily report first.</strong> Finalizing is blocked so unsaved local changes cannot be discarded.</div>':''}<label class="finalizing-confirm"><input type="checkbox" name="finalizing.confirmation"${state.finalizingAcknowledged?' checked':''}${dirty?' disabled':''}><span>I understand that daily reporting will close and this project will move to Finalizing.</span></label><div class="daily-sheet-actions"><button class="button" type="button" data-daily-action="close-modal">CANCEL</button><button class="button finalizing-confirm-button" type="button" data-daily-action="confirm-finalizing"${!state.finalizingAcknowledged||dirty||state.busy?' disabled':''}>${state.busy?'MOVING…':'CONFIRM FINALIZING'}</button></div></section></div>`;}
  const gallery=refs=>refs.map(ref=>`<span><img src="${esc(source(ref))}" alt="Evidence picture"><button type="button" data-daily-action="remove-modal-photo" data-ref="${esc(ref.assetId||ref.localId)}" aria-label="Remove picture">×</button></span>`).join('');
  function fiveSCompletionErrors(item){const errors={};if(!item.status)errors.status='Select Pass or Fail.';if(!item.evidence.length)errors.evidence='Photo required for this 5S check.';if(item.status==='Fail'&&!item.note.trim())errors.note='Corrective note is required for a failed 5S check.';return errors;}
  function fiveSModal(state){const modal=state.modal,item=modal.draft,[,label,required,iconName,color,description]=FIVE_S.find(([key])=>key===modal.key);return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-five-s-sheet five-s-${color}" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title" style="--five-s-color:var(--five-s-${color})"><div class="daily-sheet-heading"><div class="five-s-modal-identity"><span class="five-s-modal-icon">${icon(iconName,`${label} icon`)}</span><div><span class="project-eyebrow">${required?'PHOTO EVIDENCE REQUIRED':'OPTIONAL CHECK · PHOTO REQUIRED IF EVALUATED'}</span><h3 id="daily-sheet-title">${esc(label)}</h3><p>${esc(description)}</p></div></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><div class="daily-sheet-upload"><label class="evidence-upload">TAKE PHOTO / UPLOAD PHOTO<input type="file" accept="image/*" capture="environment" data-daily-upload="fiveS-modal"></label><div class="daily-thumbnails">${gallery(item.evidence)}</div><small class="field-error">${esc(modal.errors?.evidence||'')}</small></div><fieldset class="daily-status-choice"><legend>STATUS *</legend><label><input type="radio" name="modal.status" value="Pass"${item.status==='Pass'?' checked':''}><span>PASS</span></label><label><input type="radio" name="modal.status" value="Fail"${item.status==='Fail'?' checked':''}><span>FAIL</span></label><small class="field-error">${esc(modal.errors?.status||'')}</small></fieldset><label>NOTE${item.status==='Fail'?' *':''}<textarea name="modal.note" rows="3">${esc(item.note)}</textarea><small class="field-error">${esc(modal.errors?.note||'')}</small></label><div class="daily-sheet-actions"><button class="button" type="button" data-daily-action="close-modal">CANCEL</button><button class="button button-primary five-s-save" type="button" data-daily-action="save-five-s">SAVE CHECK</button></div></section></div>`;}
  const fieldError=(state,path)=>esc(state.errors?.find(error=>error.path===path)?.message||'');
  function productionModule(state){const report=state.report;return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-module-sheet daily-production-sheet" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div class="daily-module-heading"><span class="daily-module-icon">${icon('document')}</span><div><span class="project-eyebrow">01 · TODAY'S DAILY REPORT</span><h3 id="daily-sheet-title">Production Report</h3><p>Record today's production data, work performed and any issues.</p></div></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><div class="daily-identity-grid"><label data-daily-path="reportDate">REPORT DATE *<input type="date" name="reportDate" value="${esc(report.reportDate)}"><small class="field-error">${fieldError(state,'reportDate')}</small></label><label data-daily-path="shift">SHIFT *<select name="shift">${['Day','Night','Other'].map(value=>`<option${report.shift===value?' selected':''}>${value}</option>`).join('')}</select><small class="field-error">${fieldError(state,'shift')}</small></label>${report.shift==='Other'?`<label>CUSTOM SHIFT<input name="customShift" maxlength="100" value="${esc(report.customShift)}"></label>`:''}<label data-daily-path="submittedBy">SUBMITTED BY *<input name="submittedBy" maxlength="120" value="${esc(report.submittedBy)}"><small class="field-error">${fieldError(state,'submittedBy')}</small></label></div><div class="daily-quantity-grid"><label data-daily-path="completedQty">COMPLETED QTY *<input type="number" min="0" step="1" name="completedQty" value="${report.completedQty}"><small class="field-error">${fieldError(state,'completedQty')}</small></label><label>RE-WORK QTY<input type="number" min="0" step="1" name="reworkQty" value="${report.reworkQty}"></label><label>DEFECTIVE QTY<input type="number" min="0" step="1" name="defectiveQty" value="${report.defectiveQty}"></label><label>HOLD QTY<input type="number" min="0" step="1" name="holdQty" value="${report.holdQty}"></label></div><div class="daily-work-grid"><label data-daily-path="workPerformed">WORK PERFORMED *<textarea name="workPerformed" rows="4">${esc(report.workPerformed)}</textarea><small class="field-error">${fieldError(state,'workPerformed')}</small></label><fieldset class="daily-issues-compact" data-daily-path="issueStatus"><legend>ISSUES TODAY? *</legend><div><label><input type="radio" name="issueStatus" value="No"${report.issueStatus==='No'?' checked':''}><span>NO ISSUE</span></label><label><input type="radio" name="issueStatus" value="Yes"${report.issueStatus==='Yes'?' checked':''}><span>ISSUE FOUND</span></label></div><small class="field-error">${fieldError(state,'issueStatus')}</small></fieldset></div>${report.issueStatus==='Yes'?`<div class="daily-issue-details"><label data-daily-path="issueDescription">ISSUE DESCRIPTION *<textarea name="issueDescription" rows="3">${esc(report.issueDescription)}</textarea><small class="field-error">${fieldError(state,'issueDescription')}</small></label><label data-daily-path="actionTaken">ACTION TAKEN *<textarea name="actionTaken" rows="3">${esc(report.actionTaken)}</textarea><small class="field-error">${fieldError(state,'actionTaken')}</small></label></div>`:''}<div class="daily-sheet-actions"><button class="button button-primary" type="button" data-daily-action="close-modal">DONE</button></div></section></div>`;}
  function validatedProductionModule(project,state){const quantity=quantityContext(project,state.report),context=`<div class="daily-quantity-context"><div><span>PROJECT TOTAL</span><strong>${quantity.projectQuantity}</strong></div><div><span>ALREADY COMPLETED</span><strong>${quantity.previouslyCompleted}</strong></div><div><span>AVAILABLE TO COMPLETE</span><strong>${quantity.availableQuantity}</strong></div></div>${quantity.valid?'':`<div class="daily-quantity-error"><strong>QUANTITY EXCEEDS PROJECT TOTAL</strong><span>Entered: ${quantity.attemptedCompleted} · Available: ${quantity.availableQuantity}</span><small>Update the Project Total Quantity first if additional production has been approved.</small></div>`}`;return productionModule(state).replace('<div class="daily-quantity-grid">',`${context}<div class="daily-quantity-grid">`).replace('name="completedQty"',`max="${quantity.availableQuantity}" aria-invalid="${quantity.valid?'false':'true'}" name="completedQty"`).replace('data-daily-action="close-modal">DONE','data-daily-action="complete-production"'+(quantity.valid?'':' disabled')+'>DONE');}
  function evidenceModule(state){const report=state.report,count=report.productionEvidence.length;return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-module-sheet daily-evidence-sheet" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div class="daily-module-heading"><span class="daily-module-icon">${icon('camera')}</span><div><span class="project-eyebrow">02 · PHOTO EVIDENCE REQUIRED</span><h3 id="daily-sheet-title">Production Evidence</h3><p>Upload photos or take pictures of today's production evidence.</p></div></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><div class="daily-sheet-upload" data-daily-path="productionEvidence"><label class="evidence-upload">TAKE PHOTO / UPLOAD PHOTO<input type="file" accept="image/*" capture="environment" data-daily-upload="productionEvidence"></label><div class="daily-thumbnails daily-evidence-gallery">${report.productionEvidence.map(ref=>`<span><img src="${esc(source(ref))}" alt="Production evidence picture"><button type="button" data-daily-action="remove-photo" data-ref="${esc(ref.assetId||ref.localId)}" aria-label="Remove picture">×</button></span>`).join('')}</div><small class="field-error">${fieldError(state,'productionEvidence')}</small></div><div class="daily-evidence-count"><strong>${count}</strong><span>PHOTO${count===1?'':'S'} ADDED</span></div><div class="daily-sheet-actions"><button class="button button-primary" type="button" data-daily-action="close-modal">DONE</button></div></section></div>`;}
  function fiveSModule(state){const score=fiveSScore(state.report),requiredDone=FIVE_S.filter(([key,,required])=>required&&state.report.fiveS[key].status&&state.report.fiveS[key].evidence.length).length;return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-module-sheet daily-five-s-workspace" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div class="daily-module-heading"><span class="daily-module-icon">${icon('checklist')}</span><div><span class="project-eyebrow">03 · REQUIRED 4 / 4</span><h3 id="daily-sheet-title">Daily 5S / Work Area Check</h3><p>Complete today's workplace safety and organization check.</p></div></div><button class="button" data-daily-action="close-modal">CLOSE</button></div>${fiveSChecklist(state.report)}<div class="daily-five-s-module-summary"><strong>${score.display}%</strong><span>${score.evaluated} / 6 checks evaluated · Required ${requiredDone} / 4 complete</span></div><div class="daily-sheet-actions"><button class="button button-primary" type="button" data-daily-action="close-modal">DONE</button></div></section></div>`;}
  function quantityModal(project){return `<div class="daily-sheet-backdrop"><section class="daily-sheet" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div><span class="project-eyebrow">PROJECT PROGRESS</span><h3 id="daily-sheet-title">${project.totalProjectQuantity?'Update total quantity':'Set project quantity'}</h3></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><form id="quantity-form"><label>NEW TOTAL PROJECT QUANTITY *<input type="number" min="1" step="1" name="newTotalQuantity" required></label><label>REASON FOR CHANGE *<textarea name="reason" rows="3" required></textarea></label><label>UPDATED BY *<input name="actor" value="${esc(project.updatedBy||'')}" required></label><div class="daily-sheet-actions"><button class="button" type="button" data-daily-action="close-modal">CANCEL</button><button class="button button-primary">SAVE QUANTITY</button></div></form></section></div>`;}
  function staffModal(state){return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-staff-sheet" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div><span class="project-eyebrow">IN-PROGRESS ROSTER</span><h3 id="daily-sheet-title">Manage staff</h3><p>Historical members remain in the project record.</p></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><form id="daily-staff-form">${state.staffDraft.members.map(member=>`<div class="daily-staff-editor"><label>NAME<input data-member-id="${esc(member.memberId)}" data-staff-name value="${esc(member.name)}"${member.status==='Left'?' disabled':''}></label><label>NOTE<input data-member-id="${esc(member.memberId)}" data-staff-note value="${esc(member.note||'')}"></label><span>${esc(member.status)}</span>${member.status==='Active'?`<button class="button" type="button" data-daily-action="staff-left" data-ref="${esc(member.memberId)}">MARK LEFT</button>`:''}</div>`).join('')}<button class="button" type="button" data-daily-action="staff-add">+ ADD STAFF MEMBER</button><label>UPDATED BY *<input name="actor" value="${esc(state.staffActor)}" required></label><div class="daily-sheet-actions"><button class="button" type="button" data-daily-action="close-modal">CANCEL</button><button class="button button-primary">SAVE STAFF</button></div></form></section></div>`;}
  function readinessModal(project){const categories=project.preparationReadiness?.categories||{};return `<div class="daily-sheet-backdrop"><section class="daily-sheet" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div><span class="project-eyebrow">READ-ONLY</span><h3 id="daily-sheet-title">Preparation details</h3></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><div class="daily-readiness-list">${[['workstation','Workstation'],['equipment','Equipment'],['parts','Parts / Materials'],['sopGuidebook','SOP / Guidebook'],['productionReport','Production Report Setup'],['staffingResources','Staffing / Resources']].map(([key,label])=>`<div><span>${categories[key]?.valid?'✓':'○'}</span><strong>${label}</strong><small>${categories[key]?.valid?'Ready':'Review required'}</small></div>`).join('')}</div></section></div>`;}
  function reportDetail(report){if(!report)return '';const photos=refs=>refs.map(ref=>`<img src="${esc(source(ref))}" alt="Saved daily report evidence">`).join('')||'<span>None</span>',score=fiveSScore(report);return `<div class="daily-sheet-backdrop"><section class="daily-sheet daily-report-detail" role="dialog" aria-modal="true" aria-labelledby="daily-sheet-title"><div class="daily-sheet-heading"><div><span class="project-eyebrow">DAILY REPORT · READ ONLY</span><h3 id="daily-sheet-title">${esc(report.reportId)}</h3></div><button class="button" data-daily-action="close-modal">CLOSE</button></div><dl class="activation-facts">${[['DATE',report.reportDate],['SHIFT',report.shift],['STATUS',report.status],['COMPLETED',report.completedQty],['RE-WORK',report.reworkQty],['DEFECTIVE',report.defectiveQty],['HOLD',report.holdQty],['SUBMITTED BY',report.submittedBy],['SUBMITTED AT',report.submittedAt||'—']].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value??'—')}</dd></div>`).join('')}</dl><h4>Work performed</h4><p>${esc(report.workPerformed||'—')}</p><h4>Issues</h4><p>${esc(report.issueStatus||'—')}${report.issueDescription?`: ${esc(report.issueDescription)}`:''}</p>${report.actionTaken?`<p><b>Action:</b> ${esc(report.actionTaken)}</p>`:''}<h4>Staff snapshot</h4><p>${report.staffingSnapshot?.map(member=>esc(member.name)).join(', ')||'No active staff captured.'}</p><h4>5S results · ${score.display}% evaluated</h4><div class="daily-detail-five-s">${FIVE_S.map(([key,label,,iconName,color])=>{const item=report.fiveS?.[key]||{},status=item.status||'Not evaluated';return `<article class="five-s-${color}" style="--five-s-color:var(--five-s-${color})"><span class="five-s-detail-icon">${icon(iconName)}</span><div><b>${esc(label)}</b><span class="five-s-status ${status==='Pass'?'is-pass':status==='Fail'?'is-fail':''}">${esc(status)}</span><small>${cameraIcon()} ${item.evidence?.length||0} photo${item.evidence?.length===1?'':'s'}</small></div>${item.note?`<p>${esc(item.note)}</p>`:''}<div class="daily-detail-photos">${photos(item.evidence||[])}</div></article>`;}).join('')}</div><h4>Production evidence</h4><div class="daily-detail-photos">${photos(report.productionEvidence||[])}</div></section></div>`;}
  function modal(project,state){if(!state.modal)return '';if(state.modal.type==='production')return validatedProductionModule(project,state);if(state.modal.type==='evidence')return evidenceModule(state);if(state.modal.type==='fiveSWorkspace')return fiveSModule(state);if(state.modal.type==='fiveS')return fiveSModal(state);if(state.modal.type==='quantity')return quantityModal(project);if(state.modal.type==='staff')return staffModal(state);if(state.modal.type==='readiness')return readinessModal(project);if(state.modal.type==='report')return reportDetail(state.modal.report);if(state.modal.type==='finalizing')return finalizingModal(project,state);return '';}
  function render(project,state){return `<div class="in-progress-workspace"><div class="in-progress-primary"><main>${reportForm(project,state)}</main><aside>${projectProgress(project)}${activeStaff(project)}${readiness(project)}${project.note?`<section class="daily-side-card daily-note"><span class="project-eyebrow">PROJECT NOTE</span><p>${esc(project.note)}</p></section>`:''}</aside></div>${history(project)}${finalizingPanel(project)}${modal(project,state)}</div>`;}
  async function readPicture(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('Choose a JPEG, PNG or WebP picture up to 20 MiB.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return {type:'image/jpeg',base64:canvas.toDataURL('image/jpeg',.85).split(',')[1]};}finally{bitmap.close();}}
  function create({root,project:initial,request,onProject,message}){
    let project=initial,timers=[];const firstDraft=(initial.dailyReportData.reports||[]).find(report=>report.status==='Draft'),state={report:normalizedReport(firstDraft||emptyReport(initial)),modal:null,staffDraft:null,staffActor:initial.updatedBy||'',busy:false,failed:false,failure:null,progress:null,lastAction:null,errors:[],finalizingAcknowledged:false};state.baseline=reportSnapshot(state.report);
    const draw=()=>root.querySelector('.in-progress-workspace')?.replaceWith(document.createRange().createContextualFragment(render(project,state))),clear=path=>{state.errors=state.errors.filter(error=>error.path!==path);};
    const reportErrors=()=>{const report=state.report,errors=[],add=(path,message)=>errors.push({path,message});if(!report.reportDate)add('reportDate','Report date is required.');if(!report.shift)add('shift','Shift is required.');if(!Number.isInteger(Number(report.completedQty))||Number(report.completedQty)<0)add('completedQty','Completed quantity must be a nonnegative whole number.');else{const quantity=quantityContext(project,report);if(!quantity.valid)errors.push(quantityValidationError(quantity));}if(!report.workPerformed.trim())add('workPerformed','Work performed is required.');if(!report.submittedBy.trim())add('submittedBy','Submitted by is required.');if(!['No','Yes'].includes(report.issueStatus))add('issueStatus','Select whether there were issues today.');if(report.issueStatus==='Yes'&&!report.issueDescription.trim())add('issueDescription','Issue description is required.');if(report.issueStatus==='Yes'&&!report.actionTaken.trim())add('actionTaken','Action taken is required.');if(!report.productionEvidence.length)add('productionEvidence','At least one production evidence picture is required.');for(const [key,,required] of FIVE_S){const item=report.fiveS[key];if(required&&!item.status)add(`fiveS.${key}.status`,'Evaluate this required 5S check.');if((required||item.status)&&!item.evidence.length)add(`fiveS.${key}.evidence`,'Photo required for this 5S check.');if(item.status==='Fail'&&!item.note.trim())add(`fiveS.${key}.note`,'Corrective note is required for a failed 5S check.');}return errors;};
    function showErrors(focus=true){root.querySelectorAll('[data-daily-path]').forEach(node=>{node.classList.remove('is-invalid');node.querySelector('.field-error')?.replaceChildren();});let first;for(const error of state.errors){let node=root.querySelector(`[data-daily-path="${error.path}"]`);if(!node&&error.path.startsWith('fiveS.'))node=root.querySelector(`[data-daily-path="${error.path.replace(/\.(evidence|note)$/,'.status')}"]`);if(node){node.classList.add('is-invalid');const fieldError=node.querySelector('.field-error');if(fieldError)fieldError.textContent=[fieldError.textContent,error.message].filter(Boolean).join(' ');first||=node.querySelector('input,select,textarea,button')||node;}}if(focus&&first){first.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>first.focus?.(),200);}}
    function setProgress(percent,label){state.progress={percent,label};const panel=root.querySelector('.daily-action-progress');if(panel){panel.querySelector('strong').textContent=label;panel.querySelector('b').textContent=`${percent}%`;panel.querySelector('[role=progressbar]').setAttribute('aria-valuenow',percent);panel.querySelector('.save-progress-track span').style.width=`${percent}%`;}}
    async function save(action){if(state.busy)return;state.lastAction=action;if(action==='Submitted'){state.errors=reportErrors();if(state.errors.length){const quantity=quantityContext(project,state.report),quantityInvalid=state.errors.some(error=>error.code==='COMPLETED_QUANTITY_EXCEEDS_PROJECT_TOTAL');state.failure=quantityInvalid?{kind:'validation',title:'VALIDATION FAILED',message:`Completed quantity ${quantity.attemptedCompleted} exceeds available quantity ${quantity.availableQuantity}. Correct Production Report 01 or update the Project Total Quantity.`,details:quantity,retryable:false}:null;state.failed=Boolean(state.failure);draw();showErrors();message(`${state.errors.length} daily report items need attention.`,true);return;}}state.busy=true;state.failed=false;state.failure=null;root.querySelectorAll('.daily-report-form button,.daily-report-form input,.daily-report-form select,.daily-report-form textarea').forEach(control=>{control.disabled=true;});setProgress(50,action==='Draft'?'SAVING DRAFT':'SUBMITTING REPORT');try{const report=structuredClone(state.report);for(const key of ['completedQty','reworkQty','defectiveQty','holdQty'])report[key]=Number(report[key]);project=await request('put',`/api/projects/${encodeURIComponent(project.projectId)}/daily-report`,{report,action,expectedRevision:project.dailyReportData.revision,actor:report.submittedBy||'Warehouse Operator'});state.progress={percent:100,label:action==='Draft'?'DRAFT SAVED':'REPORT SUBMITTED'};state.busy=false;state.report=action==='Submitted'?emptyReport(project):normalizedReport(project.dailyReportData.reports.find(saved=>saved.reportId===report.reportId||saved.requestId===report.requestId)||state.report);state.baseline=reportSnapshot(state.report);onProject(project);draw();message(action==='Draft'?'Draft saved.':'Daily report submitted and project progress recalculated.');}catch(error){state.busy=false;state.failed=true;state.errors=error.validationErrors||[];const quantityRejected=state.errors.some(item=>item.code==='COMPLETED_QUANTITY_EXCEEDS_PROJECT_TOTAL'),stale=error.code==='PROJECT_REVISION_CONFLICT';state.failure={kind:quantityRejected||stale?'validation':'persistence',title:stale?'PROJECT DATA CHANGED':quantityRejected?'VALIDATION FAILED':'SAVE FAILED',message:stale?`The Project quantity or completed production changed after this report was opened.${Number.isFinite(error.details?.availableQuantity)?` Latest available quantity: ${error.details.availableQuantity}.`:''} Review the latest Project values before continuing.`:error.message||'Unable to save the Daily Report.',details:quantityRejected?error.details:null,retryable:!quantityRejected&&!stale&&(error.retryable||!state.errors.length)};draw();showErrors(false);message(`Daily report failed: ${error.message}`,true);}}
    async function input(event){if(!event.target.closest('.in-progress-workspace')||state.busy)return;if(event.target.hasAttribute('data-staff-name')||event.target.hasAttribute('data-staff-note')){const member=state.staffDraft?.members.find(item=>item.memberId===event.target.dataset.memberId);if(member)member[event.target.hasAttribute('data-staff-name')?'name':'note']=event.target.value;return;}const name=event.target.name;if(!name)return;if(name==='finalizing.confirmation'){state.finalizingAcknowledged=event.target.checked;draw();return;}if(state.modal?.type==='staff'&&name==='actor'){state.staffActor=event.target.value;return;}if(name==='modal.status'){state.modal.draft.status=event.target.value;state.modal.errors={};draw();return;}if(name==='modal.note'){state.modal.draft.note=event.target.value;return;}if(name==='issueStatus'||name==='shift'){state.report[name]=event.target.value;clear(name);draw();return;}state.report[name]=event.target.value;clear(name);if(name==='completedQty'){state.failure=null;state.failed=false;}}
    async function change(event){const node=event.target;if(node.name==='completedQty'&&!node.dataset.dailyUpload){draw();return;}if(!node.dataset.dailyUpload||!node.files[0])return;event.stopPropagation();try{const ref={localId:uid('photo'),pendingImage:await readPicture(node.files[0])};if(node.dataset.dailyUpload==='fiveS-modal'){state.modal.draft.evidence.push(ref);state.modal.errors={};}else{state.report.productionEvidence.push(ref);clear('productionEvidence');}draw();message('Picture added to this report draft.');}catch(error){message(error.message,true);}}
    async function finalizeProject(){if(state.busy||!state.finalizingAcknowledged||hasUnsavedReport(state))return;state.busy=true;draw();try{project=await request('post',`/api/projects/${encodeURIComponent(project.projectId)}/finalize`,{actor:state.report.submittedBy||project.updatedBy||'Warehouse Operator'});state.modal=null;state.busy=false;onProject(project);message('Project moved to Finalizing.');}catch(error){state.busy=false;draw();message(`Finalizing failed: ${error.message}`,true);}}
    function guardProductionDone(event){const button=event.target.closest?.('[data-daily-action="complete-production"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const quantity=quantityContext(project,state.report);if(!quantity.valid){state.errors=[...state.errors.filter(error=>error.path!=='completedQty'),quantityValidationError(quantity)];draw();showErrors();return;}state.modal=null;state.errors=state.errors.filter(error=>error.path!=='completedQty');draw();}
    async function click(event){const button=event.target.closest('[data-daily-action]');if(!button)return;event.preventDefault();event.stopPropagation();const action=button.dataset.dailyAction;if(action==='save-draft'||action==='submit-report')return save(action==='save-draft'?'Draft':'Submitted');if(action==='retry')return save(state.lastAction);if(action==='open-finalizing'){state.finalizingAcknowledged=false;state.modal={type:'finalizing'};draw();return;}if(action==='confirm-finalizing')return finalizeProject();if(action==='open-module'){state.modal={type:button.dataset.ref==='fiveS'?'fiveSWorkspace':button.dataset.ref};draw();return;}if(action==='open-five-s'){const key=button.dataset.ref;state.modal={type:'fiveS',key,draft:structuredClone(state.report.fiveS[key]),errors:{},returnTo:'fiveSWorkspace'};draw();return;}if(action==='save-five-s'){const item=state.modal.draft,errors=fiveSCompletionErrors(item);if(Object.keys(errors).length){state.modal.errors=errors;draw();return;}const key=state.modal.key,returnTo=state.modal.returnTo;state.report.fiveS[key]=item;state.modal=returnTo?{type:returnTo}:null;state.errors=state.errors.filter(error=>!error.path.startsWith(`fiveS.${key}.`));draw();return;}if(action==='close-modal'){state.modal=state.modal?.type==='fiveS'&&state.modal.returnTo?{type:state.modal.returnTo}:null;state.staffDraft=null;draw();return;}if(action==='remove-modal-photo'){const list=state.modal.draft.evidence,index=list.findIndex(ref=>(ref.assetId||ref.localId)===button.dataset.ref);if(index>=0)list.splice(index,1);draw();return;}if(action==='remove-photo'){const index=state.report.productionEvidence.findIndex(ref=>(ref.assetId||ref.localId)===button.dataset.ref);if(index>=0)state.report.productionEvidence.splice(index,1);draw();return;}if(action==='open-quantity'){state.modal={type:'quantity'};draw();return;}if(action==='open-staff'){state.staffDraft=structuredClone(project.staffingData);state.staffActor=project.updatedBy||'';state.modal={type:'staff'};draw();return;}if(action==='open-readiness'){state.modal={type:'readiness'};draw();return;}if(action==='view-report'){state.modal={type:'report',report:project.dailyReportData.reports.find(report=>report.reportId===button.dataset.ref)};draw();return;}if(action==='open-report'){const draft=project.dailyReportData.reports.find(report=>report.reportId===button.dataset.ref&&report.status==='Draft');if(draft){state.report=normalizedReport(draft);state.baseline=reportSnapshot(state.report);state.errors=[];draw();root.querySelector('#daily-report-form')?.scrollIntoView({behavior:'smooth'});}return;}if(action==='staff-add'){state.staffDraft.members.push({memberId:uid('STAFF'),name:'',note:'',status:'Active'});draw();return;}if(action==='staff-left'){state.staffDraft.members.find(member=>member.memberId===button.dataset.ref).status='Left';draw();}}
    async function submit(event){if(event.target.id==='quantity-form'){event.preventDefault();event.stopPropagation();try{project=await request('put',`/api/projects/${encodeURIComponent(project.projectId)}/quantity`,Object.fromEntries(new FormData(event.target)));state.modal=null;onProject(project);draw();message('Project quantity updated and progress recalculated.');}catch(error){message(error.message,true);}return;}if(event.target.id==='daily-staff-form'){event.preventDefault();event.stopPropagation();for(const member of state.staffDraft.members){const name=event.target.querySelector(`[data-member-id="${member.memberId}"][data-staff-name]`),note=event.target.querySelector(`[data-member-id="${member.memberId}"][data-staff-note]`);if(name)member.name=name.value;if(note)member.note=note.value;}const actor=new FormData(event.target).get('actor');try{project=await request('put',`/api/projects/${encodeURIComponent(project.projectId)}/staffing`,{data:{schemaVersion:1,members:state.staffDraft.members.map(({memberId,name,status,note})=>({memberId,name,status,note}))},expectedRevision:project.staffingData.revision,actor});state.modal=null;state.staffDraft=null;onProject(project);draw();message('Staffing updated.');}catch(error){message(error.message,true);}}}
    root.addEventListener('input',input,true);root.addEventListener('change',change,true);root.addEventListener('click',guardProductionDone,true);root.addEventListener('click',click,true);root.addEventListener('submit',submit,true);return{destroy(){timers.forEach(clearTimeout);root.removeEventListener('input',input,true);root.removeEventListener('change',change,true);root.removeEventListener('click',guardProductionDone,true);root.removeEventListener('click',click,true);root.removeEventListener('submit',submit,true);},state:()=>state};
  }
  window.MkiteProjectInProgress={render,create,_test:{emptyReport,FIVE_S,normalizedReport,fiveSCompletionErrors,fiveSScore,moduleState,quantityContext,quantityValidationError,icon,reportSnapshot,reportCounts,hasUnsavedReport,finalizingPanel,finalizingModal}};
}(window));
